// Documents schema (spec §6 "documents" block): documents, document_versions,
// snapshots. Owned by T07 (issue #7) — table DDL only; RLS policies belong to
// M1/T02 (see SPEC-NOTE in identity.ts).
//
// Conventions (spec §4): snake_case columns, camelCase TS fields, timestamptz
// in UTC, UUIDv7 ids generated by the app (never by the DB).

import { pgTable, text, timestamp, uniqueIndex, index, integer, jsonb, uuid } from "drizzle-orm/pg-core";
import { users, workspaces } from "./identity.ts";

export const documents = pgTable(
  "documents",
  {
    id: uuid("id").primaryKey(),
    workspaceId: uuid("workspace_id")
      .notNull()
      .references(() => workspaces.id, { onDelete: "cascade" }),
    // form | page | portfolio — plain text per spec §6 DDL (no DB enum)
    type: text("type").notNull(),
    title: text("title").notNull(),
    // unique per workspace (spec §6 UNIQUE (workspace_id, slug))
    slug: text("slug").notNull(),
    // draft | published | archived
    status: text("status").notNull().default("draft"),
    // optimistic concurrency counter, bumped by PATCH /documents/{id} (spec §8)
    rev: integer("rev").notNull().default(0),
    // current working body (DocumentBody JSON, spec §7)
    draft: jsonb("draft").notNull(),
    publishedVersionId: uuid("published_version_id"),
    createdBy: uuid("created_by").references(() => users.id),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
    updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (table) => [
    uniqueIndex("documents_workspace_id_slug_unique").on(table.workspaceId, table.slug),
    // dashboard list ordering (spec §6: index on documents (workspace_id, updated_at desc))
    index("documents_workspace_id_updated_at_idx").on(table.workspaceId, table.updatedAt.desc()),
  ],
);

export const documentVersions = pgTable("document_versions", {
  id: uuid("id").primaryKey(),
  documentId: uuid("document_id")
    .notNull()
    .references(() => documents.id, { onDelete: "cascade" }),
  workspaceId: uuid("workspace_id").notNull(),
  schemaVersion: integer("schema_version").notNull(),
  // immutable DocumentBody JSON (spec §6: insert-only, never updated)
  body: jsonb("body").notNull(),
  createdBy: uuid("created_by").references(() => users.id),
  createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
});

export const snapshots = pgTable("snapshots", {
  // one snapshot per document (spec §6: primary key document_id)
  documentId: uuid("document_id")
    .primaryKey()
    .references(() => documents.id, { onDelete: "cascade" }),
  versionId: uuid("version_id")
    .notNull()
    .references(() => documentVersions.id),
  // resolved theme, assets, compiled logic (spec §8 Snapshot JSON)
  rendered: jsonb("rendered").notNull(),
  etag: text("etag").notNull(),
  builtAt: timestamp("built_at", { withTimezone: true }).notNull().defaultNow(),
});

export const documentStatusValues = ["draft", "published", "archived"] as const;
export type DocumentStatus = (typeof documentStatusValues)[number];
export const documentTypeValues = ["form", "page", "portfolio"] as const;
export type DbDocumentType = (typeof documentTypeValues)[number];

export type DocumentRow = typeof documents.$inferSelect;
export type NewDocumentRow = typeof documents.$inferInsert;
// SPEC-NOTE: named *TableRow (not DocumentVersionRow) to avoid colliding
// with the raw row type exported by repositories/document-versions.ts.
export type DocumentVersionsTableRow = typeof documentVersions.$inferSelect;
export type NewDocumentVersionsTableRow = typeof documentVersions.$inferInsert;
export type SnapshotRow = typeof snapshots.$inferSelect;
export type NewSnapshotRow = typeof snapshots.$inferInsert;

export const documentTables = { documents, documentVersions, snapshots } as const;
